<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
Auth::requireLogin();
$pdo=Database::connection();Auth::ensureUserSchema();ensure_member_soft_delete_schema($pdo);
$id=(int)($_GET['id']??$_POST['id']??0);if($id<=0){http_response_code(400);exit('Lid ontbreekt.');}
function ensure_access_schema(PDO $pdo):void{$pdo->exec("CREATE TABLE IF NOT EXISTS member_activation_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,member_id INT UNSIGNED NOT NULL,code_hash CHAR(64) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_by_user_id INT UNSIGNED NULL,INDEX idx_mac_member(member_id),INDEX idx_mac_expiry(expires_at),CONSTRAINT fk_mac_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}
ensure_access_schema($pdo);
$s=$pdo->prepare('SELECT * FROM members WHERE id=:id AND deleted_at IS NULL');$s->execute(['id'=>$id]);$m=$s->fetch();if(!$m){http_response_code(404);exit('Lid niet gevonden.');}
$msg='';$err='';$newCode='';

// Ledenfiche is de bron voor het e-mailadres van gewone ledenaccounts.
// Als een beheerder het adres op de ledenfiche wijzigt, synchroniseren we de login automatisch.
$memberEmail=strtolower(trim((string)($m['email']??'')));
$q=$pdo->prepare('SELECT id,email,is_active,last_login_at FROM users WHERE member_id=:id AND role="member" LIMIT 1');$q->execute(['id'=>$id]);$existingUser=$q->fetch();
if($existingUser&&$memberEmail!==''&&filter_var($memberEmail,FILTER_VALIDATE_EMAIL)&&strtolower((string)$existingUser['email'])!==$memberEmail){
    try{
        $check=$pdo->prepare('SELECT id FROM users WHERE LOWER(email)=:email AND id<>:id LIMIT 1');$check->execute(['email'=>$memberEmail,'id'=>$existingUser['id']]);
        if($check->fetchColumn()){
            $err='Het e-mailadres op de ledenfiche is al gekoppeld aan een andere login. De login werd daarom niet aangepast.';
        }else{
            $pdo->prepare('UPDATE users SET email=:email,name=:name WHERE id=:id')->execute(['email'=>$memberEmail,'name'=>trim((string)$m['first_name'].' '.(string)$m['last_name']),'id'=>$existingUser['id']]);
            $existingUser['email']=$memberEmail;
            $msg='Het loginadres werd automatisch gelijkgesteld met het e-mailadres op de ledenfiche.';
        }
    }catch(Throwable $e){$err='Het loginadres kon niet automatisch worden gesynchroniseerd.';}
}

if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=(string)($_POST['action']??'');
 if($a==='create_account'){$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Vul een geldig e-mailadres in.');if(strlen($pw)<10)throw new RuntimeException('Wachtwoord moet minstens 10 tekens bevatten.');$q=$pdo->prepare('SELECT id FROM users WHERE member_id=:id');$q->execute(['id'=>$id]);if($q->fetchColumn())throw new RuntimeException('Dit lid heeft al een account.');$pdo->prepare('INSERT INTO users(member_id,name,email,password_hash,role,is_active) VALUES(:mid,:name,:email,:hash,"member",1)')->execute(['mid'=>$id,'name'=>trim($m['first_name'].' '.$m['last_name']),'email'=>$email,'hash'=>password_hash($pw,PASSWORD_DEFAULT)]);$pdo->prepare('UPDATE members SET email=:e WHERE id=:id')->execute(['e'=>$email,'id'=>$id]);$msg='Ledenaccount aangemaakt.';}
 elseif($a==='toggle'){$pdo->prepare('UPDATE users SET is_active=1-is_active WHERE member_id=:id AND role="member"')->execute(['id'=>$id]);$msg='Accountstatus aangepast.';}
 elseif($a==='password'){$pw=(string)($_POST['password']??'');if(strlen($pw)<10)throw new RuntimeException('Wachtwoord moet minstens 10 tekens bevatten.');$pdo->prepare('UPDATE users SET password_hash=:h WHERE member_id=:id AND role="member"')->execute(['h'=>password_hash($pw,PASSWORD_DEFAULT),'id'=>$id]);$msg='Wachtwoord aangepast.';}
 elseif($a==='activation'){$alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';$raw='';for($i=0;$i<8;$i++)$raw.=$alphabet[random_int(0,strlen($alphabet)-1)];$newCode=substr($raw,0,4).'-'.substr($raw,4);$pdo->prepare('UPDATE member_activation_codes SET expires_at=NOW() WHERE member_id=:id AND used_at IS NULL')->execute(['id'=>$id]);$pdo->prepare('INSERT INTO member_activation_codes(member_id,code_hash,expires_at,created_by_user_id) VALUES(:id,:h,DATE_ADD(NOW(),INTERVAL 30 DAY),:uid)')->execute(['id'=>$id,'h'=>hash('sha256',strtoupper(str_replace('-','',$newCode))),'uid'=>(int)($_SESSION['user_id']??0)?:null]);$msg='Nieuwe activatiecode aangemaakt. Bewaar of deel deze code nu; ze wordt niet leesbaar opgeslagen.';}
}catch(Throwable $e){$err=$e->getMessage();}}
$q=$pdo->prepare('SELECT id,email,is_active,last_login_at FROM users WHERE member_id=:id AND role="member" LIMIT 1');$q->execute(['id'=>$id]);$u=$q->fetch();$q=$pdo->prepare('SELECT created_at,expires_at,used_at FROM member_activation_codes WHERE member_id=:id ORDER BY id DESC LIMIT 1');$q->execute(['id'=>$id]);$ac=$q->fetch();
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login & toegang</title><style>body{font-family:Arial,sans-serif;background:#f5f6f8;margin:0}header{background:#111;color:#fff;padding:18px 28px}main{max-width:900px;margin:30px auto;padding:0 20px}.card{background:#fff;padding:22px;border-radius:14px;margin:16px 0;box-shadow:0 4px 18px #0001}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-weight:700;margin-bottom:6px}input{width:100%;box-sizing:border-box;padding:11px;border:1px solid #ccd2d8;border-radius:8px}.btn{display:inline-block;padding:10px 14px;border:0;border-radius:8px;background:#111;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.secondary{background:#e8ebef;color:#111}.ok{background:#e9f8ee;padding:12px}.err{background:#feecec;padding:12px}.code{font-size:28px;font-weight:800;letter-spacing:3px;background:#f3f5f7;padding:15px;border-radius:10px;display:inline-block}.muted{color:#68707a}.pw{display:flex;gap:6px}.pw button{width:44px}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><header>Heli One Members</header><main><h1>Login & toegang</h1><p><strong><?=e($m['first_name'].' '.$m['last_name'])?></strong> · <?=e($m['member_number']??'')?></p><?php if($msg):?><p class="ok"><?=e($msg)?></p><?php endif;?><?php if($err):?><p class="err"><?=e($err)?></p><?php endif;?><?php if($newCode):?><div class="card"><h2>Activatiecode</h2><div class="code"><?=e($newCode)?></div><p class="muted">Geldig gedurende 30 dagen en slechts één keer bruikbaar.</p></div><?php endif;?><div class="card"><h2>Ledenaccount</h2><?php if($u):?><p>Status: <strong><?=$u['is_active']?'Actief':'Inactief'?></strong><br>Login: <strong><?=e($u['email'])?></strong><br>Laatste login: <?=e($u['last_login_at']??'—')?></p><form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="toggle"><button class="btn secondary"><?=$u['is_active']?'Deactiveren':'Activeren'?></button></form><form method="post" style="margin-top:18px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="password"><label>Nieuw wachtwoord</label><div class="pw"><input type="password" name="password" minlength="10" required><button class="btn secondary eye" type="button">👁</button></div><p><button class="btn">Wachtwoord opslaan</button></p></form><?php else:?><p class="muted">Dit lid heeft nog geen normaal account.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="create_account"><div class="grid"><div><label>E-mail</label><input type="email" name="email" value="<?=e($m['email']??'')?>" required></div><div><label>Tijdelijk wachtwoord</label><div class="pw"><input type="password" name="password" minlength="10" required><button class="btn secondary eye" type="button">👁</button></div></div></div><p><button class="btn">Account aanmaken</button></p></form><?php endif;?></div><div class="card"><h2>Eenmalige activatie</h2><p>Voor leden zonder persoonlijk e-mailadres. Zij melden zich aan met voornaam + activatiecode en vullen daarna hun profiel aan.</p><?php if($ac):?><p class="muted">Laatste code: aangemaakt <?=e($ac['created_at'])?> · geldig tot <?=e($ac['expires_at'])?><?=$ac['used_at']?' · gebruikt '.$ac['used_at']:''?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="activation"><button class="btn">Nieuwe activatiecode</button></form></div><p><a class="btn secondary" href="/member.php?id=<?=$id?>">← Terug naar ledenfiche</a></p></main><script>document.querySelectorAll('.eye').forEach(b=>b.onclick=()=>{const i=b.parentElement.querySelector('input');i.type=i.type==='password'?'text':'password';});</script></body></html>